// Get add-on by ID
function getAddonById(id) {
    return ALL_ADDONS.find(a => a.id === id);
}

// Get all add-ons for a given industry
function getAddonsForIndustry(industry) {
    const relevantIds = INDUSTRY_APPS[industry] || INDUSTRY_APPS['other'];
    return relevantIds.map(id => getAddonById(id)).filter(Boolean);
}

// Get all add-ons in a category
function getAddonsByCategory(catId) {
    return ALL_ADDONS.filter(a => a.cat === catId);
}